// The fal mark as a 13x13 LED glyph (assets/brand: falos-mark font, U+E000). It is lit while
// agents work in the open project and dimmed when idle — here, in the tab favicon and (desktop
// app) in the Dock icon. Assets are generated by assets/brand/tools/generate.py.

import { useEffect } from 'react';
import { useStore, type State } from '../store';
import { invoke, isDesktop } from '../desktop';
import '../brand/mark.css';

const ACTIVE_JOB = new Set(['queued', 'running', 'IN_QUEUE', 'IN_PROGRESS']);

/** Something is working: a chat in this project is running (or a send is in flight), a
 *  generation job is queued/running on a node that still exists, or an agent touched the
 *  canvas in the last 30 s (cleared when it finishes). */
export function isWorking(s: State): boolean {
  const { chat } = s;
  if (chat.pending) return true;
  for (const id in chat.meta) if (chat.meta[id].state === 'running') return true;
  if (s.activity.length) return true;
  for (const node in s.jobs) {
    if (ACTIVE_JOB.has(s.jobs[node].status) && s.nodes.some((n) => n.id === node)) return true;
  }
  return false;
}

export const useWorking = () => useStore(isWorking);

/** The mark glyph, mono: lit = full text color with a soft glow and slow breathing, idle = dim. */
export function Mark({ lit, className = '' }: { lit: boolean; className?: string }) {
  const reduce = useStore((s) => s.reduceMotion);
  return (
    <span
      className={`falos-mark ${lit ? 'lit' : ''} ${reduce ? 'still' : ''} ${className}`}
      role="img"
      aria-label={lit ? 'fal OS: agents working' : 'fal OS'}
      title={lit ? 'agents working' : undefined}
    >
      {''}
    </span>
  );
}

/** <Mark> wired to the working state. */
export function WorkingMark() {
  return <Mark lit={useWorking()} />;
}

/** Mirrors the working state into the tab favicon and the desktop Dock icon. Renders nothing. */
export function BrandSync() {
  const working = useWorking();
  useEffect(() => {
    const tag = working ? 'lit' : 'dim';
    for (const el of document.querySelectorAll<HTMLLinkElement>('link[rel~="icon"]')) {
      el.href = el.type === 'image/png' ? `/favicon-${tag}-32.png` : `/favicon-${tag}.svg`;
    }
    if (isDesktop()) invoke('set_working', { working }).catch(() => { /* older shell */ });
  }, [working]);
  return null;
}
